from itertools import product

dice = [[] for _ in range(5)]

for p in product(range(12), repeat=30):
    for i in range(5):
        dice[i] = sorted(p[i*6:(i+1)*6])

    if all(sum(a > b for a, b in product(dice[i], dice[(i+1)%5])) > 18 for i in range(5)):
        print([x for die in dice for x in die])
        break
else:
    print("UNSATISFIABLE")
